import sys,unittest
from datetime import datetime,timezone
sys.path.insert(0,sys.argv.pop(1))
from loop_health import worker_observation
from jules_dispatch import COMPLETED_STATES,FAILED_STATES
class TerminalStateLabelRegression(unittest.TestCase):
 def test_terminal_state_label_regression(self):
  for state,expected in [(s,'worker_completed') for s in sorted(COMPLETED_STATES)]+[(s,'worker_failed') for s in sorted(FAILED_STATES)]:
   with self.subTest(state=state):
    task={'id':'synthetic-only','execution':{'session_id':'123','session_state':state}}
    self.assertEqual(worker_observation(task,datetime(2026,10,25,tzinfo=timezone.utc))['reason'],expected)
if __name__=='__main__':unittest.main(verbosity=2)
